# Keyword search vs embedding search
query = "how do I reset my password"

# Keyword: exact term matches
docs = [
    "Click here to reset your password",      # matches 'reset' and 'password'
    "Account recovery steps",                  # NO match by keyword
    "Reset password via email",                # matches
]

# Embedding search: matches by meaning
def embed(text):
    # In reality this returns a vector from a trained model
    return text.lower().split()

def similarity(q, d):
    q_words = set(embed(q))
    d_words = set(embed(d))
    return len(q_words & d_words) / max(len(q_words), 1)

for d in docs:
    print(f"sim={similarity(query, d):.2f}: {d}")

